WITH metrics AS (SELECT *, RANK() OVER (PARTITION BY customer_id ORDER BY monthly_fee DESC NULLS FIRST) AS monthly_fee_rank, ROW_NUMBER() OVER w_recent AS seq_no, COUNT(monthly_fee) OVER w_hist AS status_count_monthly_fee FROM subscriptions WINDOW w_recent AS (PARTITION BY plan, status ORDER BY end_date DESC, id), w_hist AS (PARTITION BY status)) SELECT id, customer_id, plan, start_date, end_date, monthly_fee, status, monthly_fee_rank, seq_no FROM metrics ORDER BY id DESC, end_date DESC LIMIT 5;
